CREATE TABLE truss.catalog_revision_custody (original_writer_xid xid8 NOT NULL, operation_ordinal bigint NOT NULL CHECK (operation_ordinal >= 0), original_revision int NOT NULL CHECK (original_revision > 0), capture_generation bigint NOT NULL CHECK (capture_generation >= 0), original_producer_profile_bytes bytea NOT NULL CHECK (octet_length(original_producer_profile_bytes) BETWEEN 1 AND 65536), original_fact_key_bytes bytea NOT NULL CHECK (octet_length(original_fact_key_bytes) BETWEEN 1 AND 65536), original_fact_key_profile_bytes bytea NOT NULL CHECK (octet_length(original_fact_key_profile_bytes) BETWEEN 1 AND 65536), original_payload_bytes bytea NOT NULL CHECK (octet_length(original_payload_bytes) BETWEEN 1 AND 4194304), original_payload_profile_bytes bytea NOT NULL CHECK (octet_length(original_payload_profile_bytes) BETWEEN 1 AND 65536), original_owner_context_bytes bytea NOT NULL CHECK (octet_length(original_owner_context_bytes) BETWEEN 1 AND 16777216), original_write_at timestamptz NOT NULL CHECK (isfinite(original_write_at) AND original_write_at >= '0001-01-01 00:00:00+00'::timestamptz AND original_write_at < '10000-01-01 00:00:00+00'::timestamptz), original_fact_clock_bytes bytea NOT NULL CHECK (octet_length(original_fact_clock_bytes) BETWEEN 1 AND 65536), PRIMARY KEY (original_writer_xid, operation_ordinal), FOREIGN KEY (original_writer_xid, operation_ordinal) REFERENCES truss.row_home_operation (original_writer_xid, operation_ordinal) ON DELETE RESTRICT, FOREIGN KEY (original_revision) REFERENCES truss.schema_rev (rev) ON DELETE RESTRICT, CHECK (((((((octet_length(original_producer_profile_bytes)::bigint + octet_length(original_fact_key_bytes)::bigint) + octet_length(original_fact_key_profile_bytes)::bigint) + octet_length(original_payload_bytes)::bigint) + octet_length(original_payload_profile_bytes)::bigint) + octet_length(original_owner_context_bytes)::bigint) + octet_length(original_fact_clock_bytes)::bigint) <= 16777216)); REVOKE ALL ON truss.catalog_revision_custody FROM public; CREATE FUNCTION truss.runtime_refuse_catalog_revision_custody_mutation_candidate() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path TO pg_catalog, pg_temp AS $$
BEGIN
 RAISE EXCEPTION 'original catalog revision custody is immutable' USING ERRCODE='55000';
END;
$$; REVOKE ALL ON FUNCTION truss.runtime_refuse_catalog_revision_custody_mutation_candidate() FROM public; CREATE TRIGGER catalog_revision_custody_immutable_row BEFORE DELETE OR UPDATE ON truss.catalog_revision_custody FOR EACH ROW EXECUTE FUNCTION truss.runtime_refuse_catalog_revision_custody_mutation_candidate(); ALTER TABLE truss.catalog_revision_custody ENABLE ALWAYS TRIGGER catalog_revision_custody_immutable_row; CREATE TRIGGER catalog_revision_custody_immutable_truncate BEFORE TRUNCATE ON truss.catalog_revision_custody EXECUTE FUNCTION truss.runtime_refuse_catalog_revision_custody_mutation_candidate(); ALTER TABLE truss.catalog_revision_custody ENABLE ALWAYS TRIGGER catalog_revision_custody_immutable_truncate